from helpers import *
import re, os, sys, math
if hasattr(sys, "set_int_max_str_digits"): sys.set_int_max_str_digits(0)

# Pages about the UNIVERSE LAWS (pc/laws) and about the real numbers behind them: how big planets and stars are, how fast light is, how old the universe is.
# The game numbers are read from pc/laws/laws_def.h, so the pages stay true when the table changes. The real numbers are from IAU nominal values, NASA fact
# sheets and the Planck, GRAVITY and Gaia papers; the ones that are measured with an error are marked about=1.
here = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(here, "..", "laws", "laws_def.h")).read()
ROW = re.compile(r'^X\((\w+),\s*(\w+),\s*"((?:[^"\\]|\\.)*)",\s*"((?:[^"\\]|\\.)*)",\s*"((?:[^"\\]|\\.)*)",\s*(-?\d+),\s*(-?\d+),\s*(-?\d+),\s*(-?\d+),\s*(-?\d+),\s*(-?\d+),\s*(-?\d+),\s*(\d+),\s*(.*)\)\s*$', re.M)
LAWS = []
for m in ROW.finditer(src):
    LAWS.append(dict(id=m.group(1), cat=m.group(2), name=m.group(3), mn=int(m.group(6)), mx=int(m.group(7)), df=int(m.group(8)), st=int(m.group(9)), xmn=int(m.group(11)), xmx=int(m.group(12)), fl=m.group(14)))
N = len(LAWS)
SIMPLE = sum(1 for l in LAWS if "A" not in re.findall(r"\b[A-Z]\b", l["fl"]))
def ways(lo, hi, step): return (hi - lo) // max(step, 1) + 1
W_NORMAL = 1
for l in LAWS: W_NORMAL *= ways(l["mn"], l["mx"], l["st"])
W_CHEAT = 1
for l in LAWS: W_CHEAT *= (l["xmx"] - l["xmn"] + 1)
presets = len(re.findall(r'^ \{ "', open(os.path.join(here, "..", "laws", "laws.c")).read(), re.M))
size = next(l for l in LAWS if l["id"] == "P_SIZE")
SZ_UP, SZ_DOWN = size["xmx"] // 4, -size["xmn"] // 4                  # the size law is in quarter steps of doubling
LY, AU, R_E = 9460730472580800, 149597870700, 6371008.8               # a light year and an astronomical unit are exact; the earth's mean radius (IUGG)
BIGGEST_R = R_E * 2 ** SZ_UP                                          # metres, for a planet of earth size on the biggest setting
byid = {l["id"]: l for l in LAWS}
def cats(c): return sum(1 for l in LAWS if l["cat"] == c)

